/bin/bash -lc "python3 - <<'PY'
import json,re
from collections import Counter
with open('packet.json') as f:
    p=json.load(f)
counts=Counter()
for i,item in enumerate(p['items'],1):
    q=item['question']
    if q.startswith('In which TSG'):
        shape='pack_lookup'
    elif q.startswith('Change request'):
        shape='decision_pack'
    elif q.startswith('Trace change'):
        shape='decision_pack_clauses'
    elif q.startswith('Which Rel-'):
        shape='release_clause'
    elif q.startswith('TSG RAN CR pack'):
        shape='pack_members'
    elif q.startswith('RAN3 recorded'):
        shape='revisions'
    else:
        shape='UNKNOWN'
    counts[shape]+=1
    print(i,item['id'],shape,' '.join(re.findall(r'R3-\\d+|RP-\\d+|Rel-\\d+|clause [\\d.]+|TS [\\d.]+|CR \\d+',q)))
print('SHAPES',json.dumps(counts))
PY"

